#!/usr/bin/env python3
"""Audit fixed-point comparability on a finite poset."""
from typing import Callable, Iterable, TypeVar
T = TypeVar("T")

def audit(points: Iterable[T], leq: Callable[[T, T], bool]) -> bool:
    values = tuple(points)
    return all(not leq(g, h) or leq(h, g) for g in values for h in values)

def main() -> None:
    divides = lambda a, b: b % a == 0
    assert audit([2, 3, 5], divides)
    assert not audit([2, 4], divides)
    print("{2,3,5} is an antichain under divisibility; {2,4} is not.")

if __name__ == "__main__":
    main()

